import ast, sys

def unused(path):
    src = open(path, encoding="utf-8").read()
    tree = ast.parse(src)
    imported = {}
    for node in ast.walk(tree):
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            for a in node.names:
                name = (a.asname or a.name).split(".")[0]
                imported[name] = node.lineno
    used = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Name):
            used.add(node.id)
        elif isinstance(node, ast.Attribute):
            pass
    # nitelik kullanimlari icin ham metinde ara
    out = []
    for name, line in imported.items():
        if name in used:
            continue
        # metin icinde 'name.' ya da 'name(' geciyor mu
        if f"{name}." in src or f"{name}(" in src or f"[{name}" in src or f"{name}]" in src:
            continue
        out.append((line, name))
    return sorted(out)

for p in ["src/diskultimate/core/bootloader.py", "src/diskultimate/core/grub.py",
          "src/diskultimate/core/efiboot.py", "src/diskultimate/core/efistore.py",
          "src/diskultimate/ui/dialogs/bootloader.py",
          "src/diskultimate/ui/dialogs/efiboot.py"]:
    rows = unused(p)
    if rows:
        print(p)
        for line, name in rows:
            print(f"   {line}: {name}")
print("bitti")
PYEOF

